from typing import List, Optional
import json
import os
import time


class Task:

    def __init__(self, name: str, idempotency_key: Optional[str]=None, retry_count: int=0):
        self.name = name
        self.idempotency_key = idempotency_key
        self.retry_count = retry_count
        self.dependencies = []
        self.status = 'PENDING'
        self.context = {}

    def add_dependency(self, task):
        self.dependencies.append(task)

    def mark_as_failed(self):
        self.status = 'FAILED'

    def merge_context(self, new_context):
        self.context.update(new_context)


class DAGExecutor:

    def __init__(self, concurrency: int=1):
        self.concurrency = concurrency
        self.tasks = []
        self.task_queue = []
        self.current_task = None
        self.checkpoint_file = 'checkpoint.jsonl'

    def schedule(self, tasks: List[Task]):
        for task in tasks:
            if any((task.idempotency_key == dep.idempotency_key for dep in task.dependencies)):
                raise ValueError(f'Cycle detected with idempotency key {task.idempotency_key}')
        self.tasks = tasks
        self.task_queue = sorted(self.tasks, key=lambda x: len(x.dependencies))
        if os.path.exists(self.checkpoint_file):
            self.recover_from_crash()

    def get_next_task(self) -> Optional[Task]:
        if not self.current_task:
            if self.task_queue:
                self.current_task = self.task_queue.pop(0)
                return self.current_task
            else:
                return None
        if self.current_task.status == 'FAILED':
            if self.current_task.retry_count > 0:
                time.sleep(2 ** (5 - self.current_task.retry_count))
                self.current_task.retry_count -= 1
                self.task_queue.append(self.current_task)
                self.current_task = None
                return self.get_next_task()
            else:
                raise RuntimeError(f'Task {self.current_task.name} failed after retries')
        if all((task.status == 'COMPLETED' for task in self.current_task.dependencies)):
            self.current_task.status = 'COMPLETED'
            self.save_checkpoint()
        if self.task_queue and len(self.task_queue) < self.concurrency:
            next_task = self.task_queue.pop(0)
            next_task.merge_context(self.current_task.context)
            return next_task
        self.current_task = None
        return self.get_next_task()

    def cancel_current_task(self):
        if self.current_task:
            self.current_task.status = 'CANCELLED'
            self.save_checkpoint()
            self.current_task = None

    def rollback_current_task(self):
        if self.current_task:
            self.current_task.status = 'PENDING'
            self.task_queue.append(self.current_task)
            self.current_task = None
            self.save_checkpoint()

    def pause_current_task(self):
        if self.current_task:
            self.current_task.status = 'PAUSED'
            self.save_checkpoint()
            self.current_task = None

    def invalidate_downstream_tasks(self, task: Task):
        for dep in task.dependencies:
            if dep.status != 'FAILED':
                dep.status = 'PENDING'
                self.task_queue.append(dep)
                self.invalidate_downstream_tasks(dep)

    def resume_from_checkpoint(self):
        if os.path.exists(self.checkpoint_file):
            with open(self.checkpoint_file, 'r') as f:
                for line in f:
                    task_data = json.loads(line)
                    task = Task(task_data['name'], task_data.get('idempotency_key'), task_data.get('retry_count'))
                    task.status = task_data['status']
                    task.context = task_data.get('context', {})
                    self.tasks.append(task)

    def recover_from_crash(self):
        if os.path.exists(self.checkpoint_file):
            with open(self.checkpoint_file, 'r') as f:
                for line in f:
                    task_data = json.loads(line)
                    task = Task(task_data['name'], task_data.get('idempotency_key'), task_data.get('retry_count'))
                    task.status = task_data['status']
                    task.context = task_data.get('context', {})
                    if task.status == 'PENDING':
                        self.task_queue.append(task)

    def save_checkpoint(self):
        with open(self.checkpoint_file, 'w') as f:
            for task in self.tasks:
                f.write(json.dumps({'name': task.name, 'idempotency_key': task.idempotency_key, 'retry_count': task.retry_count, 'status': task.status, 'context': task.context}) + '\n')
